#[test]
fn const_new_matches_new() {
    const AT_COMPILE_TIME: [Compressibility; 7] = [
        Compressibility::const_new(1234.5, CompressibilityUnit::InversePascal),
        Compressibility::const_new(1234.5, CompressibilityUnit::InverseKilopascal),
        Compressibility::const_new(1234.5, CompressibilityUnit::InverseMegapascal),
        Compressibility::const_new(1234.5, CompressibilityUnit::InverseAtmosphere),
        Compressibility::const_new(1234.5, CompressibilityUnit::InverseMillibar),
        Compressibility::const_new(1234.5, CompressibilityUnit::InverseBar),
        Compressibility::const_new(1234.5, CompressibilityUnit::InversePoundForcePerSquareInch),
    ];
    for (q, &unit) in AT_COMPILE_TIME.iter().zip(CompressibilityUnit::ALL) {
        assert_eq!(
            q.as_base().to_bits(),
            Compressibility::new(1234.5_f64, unit).as_base().to_bits(),
            "{unit:?}"
        );
    }
    for v in [0.0, -0.0, 1e-300, -2.5, 3.0e8, f64::MAX] {
        for &unit in CompressibilityUnit::ALL {
            assert_eq!(
                Compressibility::const_new(v, unit).as_base().to_bits(),
                Compressibility::<f64>::new(v, unit).as_base().to_bits()
            );
        }
    }
}

#[test]
fn in_unit_and_auto_unit_round_trip() {
    for v in [1e-9, 0.5, 1.0, 1234.5, 1e7, -3e4] {
        let q = Compressibility::from_base(v);
        let auto = q.auto_unit();
        assert_close(
            Compressibility::new(auto.value, auto.unit).as_base(),
            v,
            F64_TOL,
        );
        for &unit in CompressibilityUnit::ALL {
            let shown = q.in_unit(unit);
            assert_eq!((shown.value, shown.unit), (q.convert_to(unit), unit));
        }
    }
    assert_eq!(
        Compressibility::from_base(0.0).auto_unit().unit,
        CompressibilityUnit::InversePascal
    );
}

